package com.primehr.succession.api;
import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.security.*;import com.primehr.succession.api.SuccessionIntakeDtos.*;import com.primehr.succession.application.SuccessionIntakeService;import com.primehr.succession.domain.SuccessionCandidateEvidence;import jakarta.validation.Valid;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/primehr/v1/succession/intake") public class SuccessionIntakeController{
 private final SuccessionIntakeService service;private final SuccessionPlanningPermissionGuard permission;private final AgencyScopeResolver agency;public SuccessionIntakeController(SuccessionIntakeService s,SuccessionPlanningPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}
 @GetMapping("/cycles")public List<CycleResponse>cycles(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){agency(PrimeHrAction.ACCESS,t);return service.cycles(agency.resolveAgencyId(a));}
 @PostMapping("/cycles")@ResponseStatus(HttpStatus.CREATED)public CycleResponse createCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody CycleInput i){agency(PrimeHrAction.ADD,t);return service.createCycle(agency.resolveAgencyId(a),i,c);}
 @PutMapping("/cycles/{id}")public CycleResponse updateCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody CycleInput i){agency(PrimeHrAction.EDIT,t);return service.updateCycle(agency.resolveAgencyId(a),id,i,c);}
 @PostMapping("/cycles/{id}/{action:open|close|cancel}")public CycleResponse transitionCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition i){agency("open".equals(action)?PrimeHrAction.SUBMIT:PrimeHrAction.FINALIZE,t);return service.transitionCycle(agency.resolveAgencyId(a),id,i,action,c);}
 @GetMapping("/cycles/{id}/risk-reviews")public List<RiskResponse>risks(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permission.require(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ACCESS,t);return service.riskReviews(agency.resolveAgencyId(a),id,a.getName(),s);}
 @PostMapping("/cycles/{id}/risk-reviews")@ResponseStatus(HttpStatus.CREATED)public RiskResponse createRisk(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody RiskInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.ADD,t);return service.createRiskReview(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PutMapping("/risk-reviews/{id}")public RiskResponse updateRisk(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody RiskInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.EDIT,t);return service.updateRiskReview(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/risk-reviews/{id}/finalize")public RiskResponse finalizeRisk(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){var s=permission.require(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.FINALIZE,t);return service.finalizeRiskReview(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @GetMapping("/candidates")public List<CandidateResponse>candidates(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.ACCESS,t);return service.candidates(agency.resolveAgencyId(a),a.getName(),s);}
 @GetMapping("/candidates/{id}")public CandidateResponse candidate(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.ACCESS,t);return service.candidate(agency.resolveAgencyId(a),id,a.getName(),s);}
 @PostMapping("/candidates")@ResponseStatus(HttpStatus.CREATED)public CandidateResponse createCandidate(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody CandidateInput i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.ADD,t);return service.createCandidate(agency.resolveAgencyId(a),i,t,a.getName(),s,c);}
 @PutMapping("/candidates/{id}")public CandidateResponse updateCandidate(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody CandidateInput i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.EDIT,t);return service.updateCandidate(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/candidates/{id}/notice")public CandidateResponse notice(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody NoticeInput i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.EDIT,t);return service.sendNotice(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/candidates/{id}/consent")public CandidateResponse consent(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody ConsentInput i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.EDIT,t);return service.consent(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/candidates/{id}/submit")public CandidateResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.SUBMIT,t);return service.submit(agency.resolveAgencyId(a),id,i,t,a.getName(),s,c);}
 @PostMapping("/candidates/{id}/eligibility")public CandidateResponse eligibility(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody EligibilityInput i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.APPROVE,t);return service.decideEligibility(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/candidates/{id}/withdraw")public CandidateResponse withdraw(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition i){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.ARCHIVE,t);return service.withdraw(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping(value="/candidates/{id}/evidence",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@ResponseStatus(HttpStatus.CREATED)public EvidenceResponse upload(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@RequestParam String title,@RequestParam SuccessionCandidateEvidence.Visibility visibility,@RequestParam String retentionTag,@RequestPart("file")MultipartFile file){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.EDIT,t);return service.upload(agency.resolveAgencyId(a),id,title,visibility,retentionTag,file,a.getName(),s,c);}
 @GetMapping("/candidates/{id}/evidence/{evidenceId}/content")public ResponseEntity<InputStreamResource>download(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String evidenceId){var s=permission.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.ACCESS,t);var x=service.download(agency.resolveAgencyId(a),id,evidenceId,a.getName(),s,c);return ResponseEntity.ok().contentType(MediaType.parseMediaType(x.mediaType())).contentLength(x.size()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(x.filename()).build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").header("X-Content-Type-Options","nosniff").body(new InputStreamResource(x.stream()));}
 private void agency(PrimeHrAction action,String token){if(permission.require(SuccessionPlanningPermissionGuard.POOL,action,token)!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Succession cycle administration requires Agency Wide scope");}
}
